1	package edgefleet
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"time"
7	)
8	
9	// Heartbeat is one telemetry record reported by a node.
10	//
11	// JSON input uses snake_case field names:
12	//
13	//	node          string   node id (required, non-empty)
14	//	seq           integer  sequence number (required, > 0)
15	//	collected_at  string   RFC3339 with timezone, e.g. 2026-10-01T12:00:00+08:00 (required)
16	//	version       string   version (required, non-empty)
17	//	height        integer  block height (required, >= 0)
18	//	missed        integer  cumulative missed duties (required, >= 0)
19	type Heartbeat struct {
20		NodeID      string    `json:"node"`
21		Seq         int64     `json:"seq"`
22		CollectedAt time.Time `json:"collected_at"`
23		Version     string    `json:"version"`
24		Height      int64     `json:"height"`
25		Missed      int64     `json:"missed"`
26	}
27	
28	// heartbeatFields enumerates every field that must be explicitly provided.
29	var heartbeatFields = []string{"node", "seq", "collected_at", "version", "height", "missed"}
30	
31	// ValidateHeartbeat checks the semantic rules for one record. receiveTime is
32	// the moment the platform received the batch; a collection time later than
33	// receive time is rejected.
34	func ValidateHeartbeat(h Heartbeat, receiveTime time.Time) error {
35		if h.NodeID == "" {
36			return fmt.Errorf("node id is empty")
37		}
38		if h.Seq <= 0 {
39			return fmt.Errorf("seq must be a positive integer, got %d", h.Seq)
40		}
41		if h.Version == "" {
42			return fmt.Errorf("version is empty")
43		}
44		if h.Height < 0 {
45			return fmt.Errorf("height must be >= 0, got %d", h.Height)
46		}
47		if h.Missed < 0 {
48			return fmt.Errorf("missed must be >= 0, got %d", h.Missed)
49		}
50		if h.CollectedAt.IsZero() {
51			return fmt.Errorf("collected_at is missing or invalid")
52		}
53		if h.CollectedAt.After(receiveTime) {
54			return fmt.Errorf("collected_at %s is later than receive time %s",
55				h.CollectedAt.Format(time.RFC3339), receiveTime.Format(time.RFC3339))
56		}
57		return nil
58	}
59	
60	// Equal reports whether two records are the same telemetry. Collection times
61	// are compared as instants, so the same moment expressed in different
62	// timezones compares equal.
63	func (h Heartbeat) Equal(o Heartbeat) bool {
64		return h.NodeID == o.NodeID &&
65			h.Seq == o.Seq &&
66			h.Version == o.Version &&
67			h.Height == o.Height &&
68			h.Missed == o.Missed &&
69			h.CollectedAt.Equal(o.CollectedAt)
70	}
71	
72	// ParseHeartbeats parses a JSON array of heartbeat objects. Every field must
73	// be explicitly provided; missing or unknown fields are rejected with a
74	// specific reason.
75	func ParseHeartbeats(data []byte, receiveTime time.Time) ([]Heartbeat, error) {
76		var raw []json.RawMessage
77		if err := json.Unmarshal(data, &raw); err != nil {
78			return nil, fmt.Errorf("input must be a JSON array of heartbeat objects: %w", err)
79		}
80		if len(raw) == 0 {
81			return nil, fmt.Errorf("no heartbeat records provided")
82		}
83		records := make([]Heartbeat, 0, len(raw))
84		for i, r := range raw {
85			h, err := parseOneHeartbeat(r, receiveTime)
86			if err != nil {
87				return nil, fmt.Errorf("record %d: %w", i+1, err)
88			}
89			records = append(records, h)
90		}
91		return records, nil
92	}
93	
94	func parseOneHeartbeat(raw json.RawMessage, receiveTime time.Time) (Heartbeat, error) {
95		var fields map[string]json.RawMessage
96		if err := json.Unmarshal(raw, &fields); err != nil {
97			return Heartbeat{}, fmt.Errorf("record must be a JSON object: %w", err)
98		}
99		for _, f := range heartbeatFields {
100			if _, ok := fields[f]; !ok {
101				return Heartbeat{}, fmt.Errorf("missing required field %q", f)
102			}
103		}
104		for k := range fields {
105			if !containsString(heartbeatFields, k) {
106				return Heartbeat{}, fmt.Errorf("unknown field %q", k)
107			}
108		}
109	
110		var h Heartbeat
111	
112		if err := json.Unmarshal(fields["node"], &h.NodeID); err != nil {
113			return Heartbeat{}, fmt.Errorf("node must be a string: %w", err)
114		}
115		if h.NodeID == "" {
116			return Heartbeat{}, fmt.Errorf("node must not be empty")
117		}
118	
119		if err := json.Unmarshal(fields["seq"], &h.Seq); err != nil {
120			return Heartbeat{}, fmt.Errorf("seq must be an integer: %w", err)
121		}
122		if h.Seq <= 0 {
123			return Heartbeat{}, fmt.Errorf("seq must be a positive integer, got %d", h.Seq)
124		}
125	
126		var collectedStr string
127		if err := json.Unmarshal(fields["collected_at"], &collectedStr); err != nil {
128			return Heartbeat{}, fmt.Errorf("collected_at must be a string: %w", err)
129		}
130		t, err := time.Parse(time.RFC3339, collectedStr)
131		if err != nil {
132			return Heartbeat{}, fmt.Errorf("collected_at must be RFC3339 with timezone (e.g. 2026-10-01T12:00:00+08:00): %w", err)
133		}
134		h.CollectedAt = t
135	
136		if err := json.Unmarshal(fields["version"], &h.Version); err != nil {
137			return Heartbeat{}, fmt.Errorf("version must be a string: %w", err)
138		}
139		if h.Version == "" {
140			return Heartbeat{}, fmt.Errorf("version must not be empty")
141		}
142	
143		if err := json.Unmarshal(fields["height"], &h.Height); err != nil {
144			return Heartbeat{}, fmt.Errorf("height must be an integer: %w", err)
145		}
146		if h.Height < 0 {
147			return Heartbeat{}, fmt.Errorf("height must be >= 0, got %d", h.Height)
148		}
149	
150		if err := json.Unmarshal(fields["missed"], &h.Missed); err != nil {
151			return Heartbeat{}, fmt.Errorf("missed must be an integer: %w", err)
152		}
153		if h.Missed < 0 {
154			return Heartbeat{}, fmt.Errorf("missed must be >= 0, got %d", h.Missed)
155		}
156	
157		if h.CollectedAt.After(receiveTime) {
158			return Heartbeat{}, fmt.Errorf("collected_at %s is later than receive time %s",
159				h.CollectedAt.Format(time.RFC3339), receiveTime.Format(time.RFC3339))
160		}
161		return h, nil
162	}
163	
164	func containsString(list []string, s string) bool {
165		for _, v := range list {
166			if v == s {
167				return true
168			}
169		}
170		return false
171	}
