1	// Command edgefleet is the 验证者与边缘节点机群管理平台 entry point.
2	package main
3	
4	import (
5		"flag"
6		"fmt"
7		"io"
8		"os"
9		"time"
10	
11		"github.com/asdhoaiqqq/edgefleet-validator/edgefleet"
12	)
13	
14	func main() {
15		command := "demo"
16		if len(os.Args) > 1 {
17			command = os.Args[1]
18		}
19		switch command {
20		case "demo":
21			runDemo()
22		case "version":
23			fmt.Println("edgefleet 0.1.0")
24		case "heartbeat":
25			runHeartbeat(os.Args[2:])
26		case "help", "-h", "--help":
27			usage()
28		default:
29			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
30			usage()
31			os.Exit(2)
32		}
33	}
34	
35	func usage() {
36		fmt.Println("usage: edgefleet [demo|version|heartbeat|help]")
37		fmt.Println()
38		fmt.Println("commands:")
39		fmt.Println("  demo       run the built-in evaluation demo")
40		fmt.Println("  version    print version")
41		fmt.Println("  heartbeat  receive, store and query real heartbeats")
42		fmt.Println("  help       show this help")
43		fmt.Println()
44		fmt.Println("run 'edgefleet heartbeat --help' for heartbeat input format and storage location")
45	}
46	
47	// defaultDataDir resolves the data directory: --data-dir flag, then the
48	// EDGEFLEET_DATA_DIR environment variable, then ~/.edgefleet.
49	func defaultDataDir() string {
50		if d := os.Getenv("EDGEFLEET_DATA_DIR"); d != "" {
51			return d
52		}
53		home, err := os.UserHomeDir()
54		if err != nil {
55			return ".edgefleet"
56		}
57		return home + "/.edgefleet"
58	}
59	
60	// die prints an error to stderr and exits with status 1.
61	func die(format string, args ...any) {
62		fmt.Fprintf(os.Stderr, "error: "+format+"\n", args...)
63		os.Exit(1)
64	}
65	
66	// parseTime parses an RFC3339 time flag, defaulting to now when empty.
67	func parseTimeFlag(value, flagName string) time.Time {
68		if value == "" {
69			return time.Now()
70		}
71		t, err := time.Parse(time.RFC3339, value)
72		if err != nil {
73			die("invalid %s %q: must be RFC3339 with timezone (e.g. 2026-10-01T12:00:00+08:00)", flagName, value)
74		}
75		return t
76	}
77	
78	func runHeartbeat(args []string) {
79		if len(args) == 0 {
80			heartbeatUsage()
81			return
82		}
83		switch args[0] {
84		case "submit":
85			cmdSubmit(args[1:])
86		case "health":
87			cmdHealth(args[1:])
88		case "history":
89			cmdHistory(args[1:])
90		case "help", "-h", "--help":
91			heartbeatUsage()
92		default:
93			fmt.Fprintf(os.Stderr, "unknown heartbeat command %q\n", args[0])
94			heartbeatUsage()
95			os.Exit(2)
96		}
97	}
98	
99	func heartbeatUsage() {
100		fmt.Println("usage: edgefleet heartbeat <submit|health|history> [flags]")
101		fmt.Println()
102		fmt.Println("commands:")
103		fmt.Println("  submit   receive heartbeats from stdin as a JSON array")
104		fmt.Println("  health   query node health from its latest telemetry")
105		fmt.Println("  history  list all heartbeats for a node, ascending by seq")
106		fmt.Println()
107		fmt.Println("input format (submit):")
108		fmt.Println("  A JSON array of heartbeat objects; every field is required.")
109		fmt.Println("    node          string   node id (non-empty)")
110		fmt.Println("    seq           integer  sequence number (> 0)")
111		fmt.Println("    collected_at  string   RFC3339 with timezone, e.g. 2026-10-01T12:00:00+08:00")
112		fmt.Println("                           must not be later than the receive time")
113		fmt.Println("    version       string   version (non-empty)")
114		fmt.Println("    height        integer  block height (>= 0)")
115		fmt.Println("    missed        integer  cumulative missed duties (>= 0)")
116		fmt.Println()
117		fmt.Println("  example:")
118		fmt.Println(`    [{"node":"val-eu-1","seq":7,"collected_at":"2026-10-01T11:59:00+08:00",`)
119		fmt.Println(`      "version":"1.26.0","height":12345,"missed":0}]`)
120		fmt.Println()
121		fmt.Println("flags:")
122		fmt.Println("  submit   --data-dir DIR        data directory (default: $EDGEFLEET_DATA_DIR or ~/.edgefleet)")
123		fmt.Println("           --receive-time TIME   receive time, RFC3339 (default: now)")
124		fmt.Println("  health   --node ID             node id (required)")
125		fmt.Println("           --expected-version V  expected version (required)")
126		fmt.Println("           --tolerated-misses N  tolerated missed duties, >= 0 (required)")
127		fmt.Println("           --at TIME             query time, RFC3339 (default: now)")
128		fmt.Println("           --data-dir DIR        data directory")
129		fmt.Println("  history  --node ID             node id (required)")
130		fmt.Println("           --data-dir DIR        data directory")
131		fmt.Println()
132		fmt.Println("data storage:")
133		fmt.Println("  <data-dir>/nodes/<hex-node-id>.json, one file per node.")
134		fmt.Println("  Writes are atomic and the directory is locked for concurrent access.")
135		fmt.Println("  Corrupt data is refused, never silently cleared.")
136	}
137	
138	func newFlagSet(name string) *flag.FlagSet {
139		fs := flag.NewFlagSet(name, flag.ContinueOnError)
140		fs.SetOutput(os.Stderr)
141		fs.Usage = func() { heartbeatUsage() }
142		return fs
143	}
144	
145	func cmdSubmit(args []string) {
146		fs := newFlagSet("heartbeat submit")
147		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
148		receiveStr := fs.String("receive-time", "", "receive time (RFC3339); default: now")
149		if err := fs.Parse(args); err != nil {
150			if err == flag.ErrHelp {
151				os.Exit(0)
152			}
153			os.Exit(2)
154		}
155		if fs.NArg() != 0 {
156			die("submit takes no positional arguments; heartbeats are read from stdin")
157		}
158	
159		receiveTime := parseTimeFlag(*receiveStr, "--receive-time")
160	
161		data, err := io.ReadAll(os.Stdin)
162		if err != nil {
163			die("cannot read stdin: %v", err)
164		}
165		records, err := edgefleet.ParseHeartbeats(data, receiveTime)
166		if err != nil {
167			die("invalid input: %v", err)
168		}
169	
170		store, err := edgefleet.OpenStore(*dataDir)
171		if err != nil {
172			die("%v", err)
173		}
174		newCount, dupCount, err := store.Submit(records, receiveTime)
175		if err != nil {
176			die("%v", err)
177		}
178		fmt.Printf("submitted: new=%d duplicate=%d\n", newCount, dupCount)
179	}
180	
181	func cmdHealth(args []string) {
182		fs := newFlagSet("heartbeat health")
183		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
184		node := fs.String("node", "", "node id (required)")
185		atStr := fs.String("at", "", "query time (RFC3339); default: now")
186		expectedVersion := fs.String("expected-version", "", "expected version (required)")
187		toleratedMisses := fs.Int("tolerated-misses", -1, "tolerated missed duties, >= 0 (required)")
188		if err := fs.Parse(args); err != nil {
189			if err == flag.ErrHelp {
190				os.Exit(0)
191			}
192			os.Exit(2)
193		}
194		if *node == "" {
195			die("--node is required")
196		}
197		if *expectedVersion == "" {
198			die("--expected-version is required")
199		}
200		if *toleratedMisses < 0 {
201			die("--tolerated-misses is required and must be >= 0")
202		}
203	
204		at := parseTimeFlag(*atStr, "--at")
205	
206		store, err := edgefleet.OpenStore(*dataDir)
207		if err != nil {
208			die("%v", err)
209		}
210		result, err := store.Health(*node, at, *expectedVersion, *toleratedMisses)
211		if err != nil {
212			die("%v", err)
213		}
214	
215		if result.Status == "notelemetry" {
216			fmt.Printf("node=%s status=无遥测 findings=[无遥测]\n", result.NodeID)
217			return
218		}
219		fmt.Printf("node=%s status=%s seq=%d collected_at=%s version=%s height=%d missed=%d findings=%v\n",
220			result.NodeID, result.Status, result.Seq, result.CollectedAt.Format(time.RFC3339),
221			result.Version, result.Height, result.Missed, result.Findings)
222	}
223	
224	func cmdHistory(args []string) {
225		fs := newFlagSet("heartbeat history")
226		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
227		node := fs.String("node", "", "node id (required)")
228		if err := fs.Parse(args); err != nil {
229			if err == flag.ErrHelp {
230				os.Exit(0)
231			}
232			os.Exit(2)
233		}
234		if *node == "" {
235			die("--node is required")
236		}
237	
238		store, err := edgefleet.OpenStore(*dataDir)
239		if err != nil {
240			die("%v", err)
241		}
242		records, err := store.History(*node)
243		if err != nil {
244			die("%v", err)
245		}
246		if len(records) == 0 {
247			fmt.Printf("node=%s no heartbeats\n", *node)
248			return
249		}
250		for _, r := range records {
251			fmt.Printf("node=%s seq=%d collected_at=%s version=%s height=%d missed=%d\n",
252				r.NodeID, r.Seq, r.CollectedAt.Format(time.RFC3339), r.Version, r.Height, r.Missed)
253		}
254	}
255	
256	func runDemo() {
257		nodes := []edgefleet.Node{
258			{ID: "val-eu-1", Region: "eu", Version: "1.26.0", Online: true},
259			{ID: "val-us-1", Region: "us", Version: "1.25.4", Online: true, Missed: 3},
260			{ID: "edge-ap-1", Region: "ap", Version: "1.26.0", Online: false},
261		}
262		unhealthy := 0
263		for _, node := range nodes {
264			health := edgefleet.Evaluate(node, "1.26.0", 1)
265			if !health.Healthy {
266				unhealthy++
267			}
268			fmt.Printf("node=%s healthy=%v findings=%v\n", health.Node, health.Healthy, health.Findings)
269		}
270		fmt.Println("rollout order:", edgefleet.Plan(nodes, "1.26.0"))
