48	func TestParseHeartbeatsInvalid(t *testing.T) {
49		cases := []struct {
50			name  string
51			input string
52		}{
53			{"not array", `{"node":"val-1"}`},
54			{"empty array", `[]`},
55			{"missing node", `[{"seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":1,"missed":0}]`},
56			{"missing seq", `[{"node":"val-1","collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":1,"missed":0}]`},
57			{"missing collected_at", `[{"node":"val-1","seq":1,"version":"1.0","height":1,"missed":0}]`},
58			{"missing version", `[{"node":"val-1","seq":1,"collected_at":"2026-10-01T11:59:00Z","height":1,"missed":0}]`},
59			{"missing height", `[{"node":"val-1","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","missed":0}]`},
60			{"missing missed", `[{"node":"val-1","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":1}]`},
61			{"unknown field", `[{"node":"val-1","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":1,"missed":0,"extra":5}]`},
62			{"empty node", `[{"node":"","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":1,"missed":0}]`},
63			{"seq zero", `[{"node":"val-1","seq":0,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":1,"missed":0}]`},
64			{"seq negative", `[{"node":"val-1","seq":-1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":1,"missed":0}]`},
65			{"seq float", `[{"node":"val-1","seq":1.5,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":1,"missed":0}]`},
66			{"collected_at no timezone", `[{"node":"val-1","seq":1,"collected_at":"2026-10-01T11:59:00","version":"1.0","height":1,"missed":0}]`},
67			{"collected_at garbage", `[{"node":"val-1","seq":1,"collected_at":"yesterday","version":"1.0","height":1,"missed":0}]`},
68			{"collected_at after receive", `[{"node":"val-1","seq":1,"collected_at":"2026-10-01T12:00:01Z","version":"1.0","height":1,"missed":0}]`},
69			{"empty version", `[{"node":"val-1","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"","height":1,"missed":0}]`},
70			{"height negative", `[{"node":"val-1","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":-1,"missed":0}]`},
71			{"missed negative", `[{"node":"val-1","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":1,"missed":-1}]`},
72			{"record not object", `[42]`},
73		}
74		for _, tc := range cases {
75			t.Run(tc.name, func(t *testing.T) {
76				_, err := ParseHeartbeats([]byte(tc.input), testBase)
77				if err == nil {
78					t.Errorf("expected error for %s, got nil", tc.name)
79				}
80			})
81		}
82	}
83	
84	func TestValidateHeartbeat(t *testing.T) {
85		receive := testBase
86		valid := hb("n1", 1, receive.Add(-time.Minute), "1.0", 10, 0)
87		if err := ValidateHeartbeat(valid, receive); err != nil {
88			t.Errorf("valid record rejected: %v", err)
89		}
90		// Boundary: collected exactly at receive time is allowed.
91		exact := hb("n1", 1, receive, "1.0", 10, 0)
92		if err := ValidateHeartbeat(exact, receive); err != nil {
93			t.Errorf("collected_at == receive_time should be allowed: %v", err)
94		}
95		// Boundary: height 0 and missed 0 are allowed.
96		zero := hb("n1", 1, receive.Add(-time.Minute), "1.0", 0, 0)
97		if err := ValidateHeartbeat(zero, receive); err != nil {
98			t.Errorf("zero height/missed should be allowed: %v", err)
99		}
100		// Future collection time rejected.
101		future := hb("n1", 1, receive.Add(time.Second), "1.0", 10, 0)
102		if err := ValidateHeartbeat(future, receive); err == nil {
103			t.Errorf("future collected_at should be rejected")
104		}
105	}
106	
107	func TestSubmitNewAndDuplicate(t *testing.T) {
108		store, err := OpenStore(t.TempDir())
109		if err != nil {
110			t.Fatal(err)
111		}
112		receive := testBase
