689					batch[j] = hb("n1", seq, receive.Add(-time.Duration(100-seq)*time.Second), "1.0", seq, 0)
690				}
691				if _, _, err := store.Submit(batch, receive); err != nil {
692					t.Error(err)
693					return
694				}
695				submittedMu.Lock()
696				for _, r := range batch {
697					submitted[r.Seq] = true
698				}
699				submittedMu.Unlock()
700			}(w)
701		}
702	
703		// Readers: history must always be sorted, duplicate-free, and only
704		// contain seqs that have been submitted.
705		for r := 0; r < 8; r++ {
706			wg.Add(1)
707			go func() {
708				defer wg.Done()
709				store, err := OpenStore(dir)
710				if err != nil {
711					t.Error(err)
712					return
713				}
714				for i := 0; i < 50; i++ {
715					hist, err := store.History("n1")
716					if err != nil {
717						t.Error(err)
718						return
719					}
720					var prev int64
721					seen := map[int64]bool{}
722					for _, r := range hist {
723						if r.Seq <= prev && prev != 0 {
724							t.Errorf("history not sorted: %+v", hist)
725							return
726						}
727						if seen[r.Seq] {
728							t.Errorf("duplicate seq in history: %d", r.Seq)
729							return
730						}
731						seen[r.Seq] = true
732						prev = r.Seq
733						submittedMu.Lock()
734						ok := submitted[r.Seq]
735						submittedMu.Unlock()
736						if !ok {
737							t.Errorf("history contains seq %d that was never submitted", r.Seq)
738							return
739						}
740					}
741				}
742			}()
743		}
744		wg.Wait()
745	
746		// Final state: all 20 records present.
747		store, _ := OpenStore(dir)
748		hist, err := store.History("n1")
749		if err != nil {
750			t.Fatal(err)
751		}
752		if len(hist) != 20 {
753			t.Errorf("final history count=%d, want 20", len(hist))
754		}
755	}
